/**
 * updater ACL 回归断言（修复 v0.14.x 真机 P1：三命令被 ACL 拒，UI 更新链 100% 死透）。
 *
 * 上一版 14/14 全绿却漏掉这一层的根因：老用例只做「源码里有没有 invoke 字样」的文本断言，
 * **不碰 ACL 层**，而真机拒绝发生在 ACL。本文件把 ACL 三要素钉住：
 *
 *   ① build.rs 必须**声明**这些 app 命令 —— 否则 `permissions/autogenerated/*.toml`
 *      不会生成，权限标识不存在，capabilities 里也无从引用（构建期 `__app__-permission-files`
 *      为 `[]` 就是这个状态）。
 *   ② capabilities/default.json 必须**授予**对应用户权限标识（kebab 形态）。
 *   ③ capabilities/default.json 必须声明 **remote.urls 含 https://chat.deepseek.com** ——
 *      注入脚本跑在远程 origin，Tauri v2 对远程内容默认拒绝一切自定义命令
 *      （tauri-2.12.2/src/webview/mod.rs:2076-2108 的 `!is_local` 分支）。
 *
 * 负控：删任一条目 → 本文件红。这正是上一版缺失的回归面。
 */
import { describe, expect, it } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';

const repoRoot = path.resolve(__dirname, '../..');
const buildRs = path.join(repoRoot, 'src-tauri/build.rs');
const capPath = path.join(repoRoot, 'src-tauri/capabilities/default.json');

/** 六个必须在 ACL 里被声明+授予的 app 命令（snake 名 → kebab 权限标识）。 */
const APP_COMMANDS: ReadonlyArray<{ snake: string; permission: string }> = [
  { snake: 'updater_check', permission: 'allow-updater-check' },
  { snake: 'updater_install', permission: 'allow-updater-install' },
  { snake: 'updater_progress', permission: 'allow-updater-progress' },
  { snake: 'open_workbench', permission: 'allow-open-workbench' },
  { snake: 'focus_main_window', permission: 'allow-focus-main-window' },
  { snake: 'open_bot_window', permission: 'allow-open-bot-window' },
];

describe('updater ACL（真机 P1 回归面）', () => {
  it('① build.rs 声明了全部 app 命令（否则权限标识不会生成）', () => {
    const src = fs.readFileSync(buildRs, 'utf-8');
    expect(src, 'build.rs 未使用 AppManifest::commands 声明命令').toMatch(
      /AppManifest::new\(\)\s*\.commands\(/,
    );
    for (const { snake } of APP_COMMANDS) {
      expect(src, `build.rs 未声明 ${snake}`).toContain(`"${snake}"`);
    }
  });

  it('② capabilities 授予了全部 app 命令权限', () => {
    const cap = JSON.parse(fs.readFileSync(capPath, 'utf-8')) as { permissions?: string[] };
    const perms = cap.permissions ?? [];
    for (const { snake, permission } of APP_COMMANDS) {
      expect(perms, `capabilities 缺 ${permission}（${snake} 会被 ACL 拒）`).toContain(permission);
    }
  });

  it('③ capabilities 声明了 remote.urls（远程聊天页是 ACL 的触发条件）', () => {
    const cap = JSON.parse(fs.readFileSync(capPath, 'utf-8')) as {
      remote?: { urls?: string[] };
    };
    const urls = cap.remote?.urls ?? [];
    expect(
      urls.some((u) => u.includes('chat.deepseek.com')),
      'capabilities 未声明 remote.urls → chat.deepseek.com 上的 invoke 一律被拒',
    ).toBe(true);
  });

  it('④ 权限标识形态与 Tauri 生成物一致（kebab，不是 snake）', () => {
    // 生成物由 build.rs 产出，构建后应出现对应 toml；若尚未构建则跳过文件存在性断言，
    // 但仍校验「capabilities 里用的是 kebab 形态」——避免有人写回 allow_updater_check。
    const cap = JSON.parse(fs.readFileSync(capPath, 'utf-8')) as { permissions?: string[] };
    for (const p of cap.permissions ?? []) {
      expect(p, `权限标识不应含下划线：${p}`).not.toMatch(/_/);
    }
    const genDir = path.join(repoRoot, 'src-tauri/permissions/autogenerated');
    if (fs.existsSync(genDir)) {
      for (const { snake } of APP_COMMANDS) {
        expect(
          fs.existsSync(path.join(genDir, `${snake}.toml`)),
          `生成物缺 ${snake}.toml（build.rs 声明与命令名不符？）`,
        ).toBe(true);
      }
    }
  });

  /**
   * N-02（2026-11-12 回归审计）：**签名校验不得被跳过**。
   *
   * 更新包是「从网络下载后直接执行」的代码，签名校验就是它唯一的完整性防线。
   * Tauri 提供 `dangerousSkipSignatureVerification` 这个逃生舱（CI/无签名环境常用），
   * 一旦被写进 `tauri.conf.json` 就**静默关掉**全链路验签 —— 而所有既有用例仍会绿。
   * 本断言把它钉死：出现即红。
   *
   * 配套（同一条 N-02 的另一半）：`updater_install` 的真实点击证明顺序不变式在
   * `src-tauri/src/updater.rs` 的 `confirm_runs_before_any_download_state` 里锁。
   */
  it('⑤ 不得跳过更新包签名校验（dangerousSkipSignatureVerification 必须缺席）', () => {
    const confPath = path.join(repoRoot, 'src-tauri/tauri.conf.json');
    const raw = fs.readFileSync(confPath, 'utf-8');
    expect(
      raw.includes('dangerousSkipSignatureVerification'),
      'tauri.conf.json 出现 dangerousSkipSignatureVerification ⇒ 全链路验签被静默关闭',
    ).toBe(false);

    // 装置自检：配置文件确实带 updater 段与 pubkey，否则本断言是空转（恒绿）。
    const conf = JSON.parse(raw) as { plugins?: { updater?: { pubkey?: unknown } } };
    const updater = conf.plugins?.updater;
    expect(updater, '装置自检：tauri.conf.json 应有 plugins.updater 段').toBeDefined();
    expect(updater?.pubkey, '装置自检：plugins.updater 应配 pubkey（否则验签无从谈起）').toBeDefined();
  });
});
